import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1205, own='cte_128.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("877.d.1.A",3,"A lube-bay trainee patiently explains a recommended service to a customer who speaks little English, using the vehicle's gauges and simple words. He is demonstrating:","effective oral communication with individuals from varied backgrounds",["avoiding customers","rushed talking","unclear answers"],"Adapt communication.")
H("877.d.1.A",4,"A customer says her car 'makes a funny noise sometimes.' The best follow-up from the technician is:","asking when the noise happens and what it sounds like",["telling her to come back later","guessing at the cause","ending the conversation"],"Gather details.")
H("877.d.1.B",3,"A technician writes the complaint, the cause and the correction on a repair order after replacing a worn belt. This shows:","effective written communication, including documentation",["slang","skipped records","vague notes"],"Documentation.")
H("877.d.1.B",4,"Which line is the most useful on a repair order?","'Replaced serpentine belt; tension tested at spec'",["'Fixed it'","'Looked fine'","'Did stuff'"],"Specific and verifiable.")
H("877.d.1.C",3,"A technician adds a $48 part, 2.5 hours of labor at $88 an hour and 7 percent tax on the part. She is demonstrating:","mathematical skills for estimating a repair bill",["avoiding numbers","guessing","ignoring tax"],"Compute totals.")
H("877.d.1.C",4,"Labor is 1.5 hours at $100 per hour and parts are $62. The total before tax is:","$212",["$162","$150","$262"],"150 + 62 = 212.")
H("877.d.2.A",3,"Before an inspection, a technician opens the owner's manual to find when the timing belt and fluids are due for service. She is:","locating the manufacturer's recommended preventative maintenance schedule",["guessing intervals","ignoring the manual","skipping service"],"Use the schedule.")
H("877.d.2.A",4,"A 'severe service' schedule in an owner's manual applies to vehicles that:","tow, idle a lot or drive in dusty or short-trip conditions",["are brand new","never leave the garage","are only washed"],"Harsh use.")
H("877.d.2.B",3,"A technician runs a checklist of tires, brakes, belts, lights, fluids and suspension on a customer's car. She is performing:","a preventative maintenance inspection of vehicle systems",["a body repair","a sale","a paint job"],"PM inspection.")
H("877.d.2.B",4,"Why is a preventative maintenance inspection done even when the car seems fine?","to find wear before it causes a breakdown",["to raise the bill","to waste time","to avoid work"],"Prevent failures.")
H("877.d.2.C",3,"A student names the control arms, ball joints, springs and steering knuckle on a diagram of a front suspension. She is describing:","the function of automotive chassis components",["engine parts","paint layers","radio parts"],"Chassis parts.")
H("877.d.2.C",4,"Springs in a suspension system mainly:","support the vehicle's weight and absorb road shocks",["steer the vehicle","brake the wheels","cool the engine"],"Springs support and absorb.")
H("877.d.2.D",3,"A technician follows a wiring schematic and a technical service bulletin to find the cause of an intermittent dome-light problem. She is:","locating, reading and interpreting service repair information",["guessing","ignoring data","using memory only"],"Schematics and bulletins.")
H("877.d.2.D",4,"A technical service bulletin is most useful because it:","describes known problems and approved fixes for specific vehicles",["lists car prices","advertises accessories","gives driving tips"],"TSBs document known issues.")
H("877.d.2.E",3,"A technician compares a measured brake rotor thickness with the published minimum and decides to replace it. She is:","using published specifications to diagnose component wear",["guessing","ignoring specs","painting"],"Compare to spec.")
H("877.d.2.E",4,"A rotor measures below the 'minimum thickness' stamped on it. The technician should:","replace the rotor",["machine it thinner","reuse it as is","paint it"],"Below minimum means replace.")
H("877.d.2.F",3,"A technician looks up the oil grade and capacity for a customer's engine, such as 5W-30 and 4.5 quarts. She is:","identifying the appropriate oil viscosity and capacity",["guessing","using any oil","skipping specs"],"Use the specified oil.")
H("877.d.2.F",4,"In '5W-30' oil, the '5W' indicates how the oil flows:","when cold",["when hot only","after 5 weeks","in water"],"W stands for winter.")
H("877.d.2.G",3,"When the ignition is switched on, a technician notes that the oil-pressure, check-engine and charging lights glow briefly and then go out. She is:","verifying the operation of the instrument panel engine warning indicators",["ignoring lights","guessing","painting"],"Bulb check.")
H("877.d.2.G",4,"A warning light that never comes on during the bulb check may indicate:","a burned-out bulb or a circuit fault",["a perfect system","a full tank","a new battery"],"No bulb check is suspicious.")
H("877.d.2.H",3,"A technician looks over an engine and records a seeping valve cover gasket, low coolant and a cracked hose. She is:","inspecting the engine assembly and documenting findings of fuel, oil, coolant and other leaks",["ignoring leaks","guessing","painting"],"Document leaks.")
H("877.d.2.H",4,"A fresh, wet oil stain below a valve cover most likely means:","a leaking valve cover gasket",["a bad tire","a clean engine","a dead battery"],"Locate the source.")
H("877.d.2.I",3,"A technician uses a tap, a thread-repair insert and a screw extractor to fix a stripped oil-pan hole and remove a broken bolt. She is performing:","common fastener and thread repair",["painting","guessing","avoiding repair"],"Thread repair.")
H("877.d.2.I",4,"A thread-repair insert is used to:","restore damaged threads to their original size",["cut new bolts","paint a hole","enlarge a hole permanently"],"Insert restores threads.")
H("877.d.2.J",3,"A technician checks the serpentine belt for cracks, tests the automatic tensioner and aligns the pulleys. She is:","inspecting, replacing and adjusting drive belts, tensioners and pulleys",["ignoring belts","guessing","painting"],"Belt service.")
H("877.d.2.J",4,"A squealing belt that shows glazing on its edges most likely needs:","replacement or retensioning",["more oil","more air","a new tire"],"Glazed belts slip.")
H("877.d.2.K",3,"A technician drains the old oil, installs a new filter with a lightly oiled gasket and refills to the specified capacity. She is performing:","an engine oil and filter change",["a fuel change","a tire change","a coolant flush"],"Oil change.")
H("877.d.2.K",4,"After an oil change, the technician should start the engine and check for:","leaks and the correct oil level on the dipstick",["bad tires","a loose antenna","a dirty windshield"],"Verify the job.")
H("877.d.2.L",3,"A technician connects red to the dead battery's positive, red to the donor's positive, black to the donor's negative and the final black clamp to engine ground. She is:","explaining and performing a jump-start",["recharging a phone","painting","guessing"],"Correct order.")
H("877.d.2.L",4,"Reversing the jumper cable connections on modern vehicles can:","damage electronic modules and cause a fire",["improve charging","do nothing","speed the repair"],"Polarity matters.")
H("877.d.3.A",3,"Before using an air ratchet and a torque wrench on wheel nuts, a technician checks the tool and wears eye protection. She is demonstrating:","the proper use of hand and power tools and equipment common to the trade",["careless use","ignoring safety","misusing tools"],"Tool safety.")
H("877.d.3.A",4,"Using a wrench with a cheater pipe to tighten a bolt is unsafe mainly because it can:","slip, break or over-tighten and cause injury",["improve accuracy","save tools","save time"],"Misuse hazards.")
H("877.d.3.B",3,"A technician pours used coolant into a labeled container for recycling instead of the shop drain. She is practicing:","the proper handling and disposal of environmentally hazardous materials",["dumping","ignoring rules","careless disposal"],"Hazmat practice.")
H("877.d.3.B",4,"Used engine oil rags and filters should be:","stored in approved containers and disposed of per regulations",["thrown in the drain","burned outdoors","left on the floor"],"Regulated waste.")
H("877.d.4.A",3,"A student explains that pressure applied to a fluid in a closed system is transmitted equally in all directions, which lets a small pedal force move large caliper pistons. She is explaining:","Pascal's law as it relates to the brake system",["Ohm's law","Boyle's law","Newton's law of gravity"],"Pascal's principle.")
H("877.d.4.A",4,"A master cylinder piston with 1 square inch of area pushes with 50 pounds. The pressure created is:","50 psi",["5 psi","500 psi","0.02 psi"],"50 ÷ 1 = 50.")
H("877.d.4.B",3,"A technician checks the master cylinder fluid level, brake lines, hoses and the pedal for leaks and damage. She is:","inspecting brake system components",["washing the car","painting calipers","tuning the radio"],"Inspect the system.")
H("877.d.4.B",4,"A brake hose that bulges when the pedal is pressed should be:","replaced immediately",["ignored","taped","painted"],"Bulging hose may burst.")
H("877.d.4.C",3,"A technician measures a drum's inside diameter with a drum micrometer and compares it with the maximum diameter cast on the drum. She is:","inspecting, measuring and refinishing a brake drum to specification",["guessing","ignoring specs","painting"],"Measure then refinish.")
H("877.d.4.C",4,"If a brake drum is machined beyond its discard diameter, it should be:","replaced, because it is too thin and may fail",["reused","painted","machined again"],"Discard diameter is a limit.")
H("877.d.4.D",3,"A technician removes a drum, then cleans and checks the shoes, springs, pins, clips and levers for wear. She is:","removing, cleaning and inspecting the drum brake hardware",["ignoring wear","painting","guessing"],"Inspect hardware.")
H("877.d.4.D",4,"Brake dust should be cleaned with an approved wet method or vacuum rather than blown with compressed air because:","dust can contain harmful particles",["it looks messier","it saves time","it saves money"],"Avoid airborne dust.")
H("877.d.4.E",3,"A technician applies high-temperature grease to the backing-plate pads, reassembles the shoes and sets the star adjuster so the drum just slides on. She is:","lubricating, reassembling and pre-adjusting the shoes and parking brake",["painting","guessing","avoiding service"],"Pre-adjust.")
H("877.d.4.E",4,"Grease should not be allowed to contact:","the brake lining surface",["the backing-plate pads","the adjuster threads","the pivot pins"],"Grease ruins friction.")
H("877.d.4.F",3,"A technician removes the pads, inspects the caliper slides and boots, cleans and lubricates them and reassembles the caliper. She is performing:","service on the disc brake caliper and pads",["a tire change","an alignment","an oil change"],"Caliper service.")
H("877.d.4.F",4,"A caliper that sticks on its slide pins may cause:","uneven pad wear and a pull to one side",["perfect braking","a quieter ride","longer pad life"],"Sticking slides.")
H("877.d.4.G",3,"A technician machines a rotor on a lathe and then measures its final thickness against the minimum specification. She is:","refinishing a rotor and measuring its thickness",["painting","guessing","ignoring spec"],"Machine and measure.")
H("877.d.4.G",4,"A rotor that has been machined below the minimum thickness is likely to:","overheat and crack",["last longer","brake better","weigh more"],"Thin rotors fail.")
H("877.d.4.H",3,"On a rear caliper with an integral parking brake, a technician uses a special tool to rotate and retract the piston. She is:","retracting and re-adjusting the caliper piston on an integral parking brake system",["tuning the radio","painting","guessing"],"Wind back the piston.")
H("877.d.4.H",4,"Forcing a rear caliper piston straight in with a C-clamp on an integral parking brake caliper can:","damage the piston and adjuster mechanism",["improve the repair","speed it safely","fix the pad"],"Use the proper tool.")
H("877.d.4.I",3,"A technician presses the brake pedal with the engine off, then starts the engine and notes how far the pedal sinks. She is checking:","pedal travel with and without the engine running to verify power assist operation",["tire wear","fuel economy","radio volume"],"Test the booster.")
H("877.d.4.I",4,"When a vacuum brake booster is working, starting the engine with the pedal held down should make the pedal:","drop slightly as the booster assists",["rise hard","stay unchanged","shake violently"],"Booster adds assist.")
H("877.d.4.J",3,"A technician pumps the pedal until it is firm with the engine off, holds it, and starts the engine to see what happens. She is:","verifying the operation of the power-assist system",["washing the brakes","painting rotors","testing a tire"],"Booster check.")
H("877.d.4.J",4,"If the pedal does not move down at all after starting the engine, the likely problem is:","a faulty booster or a lack of vacuum supply",["worn tires","a dead radio","low washer fluid"],"No assist.")
H("877.d.4.K",3,"A technician connects a gauge to the intake manifold and reads the vacuum that feeds the brake booster. She is:","checking the vacuum supply from the manifold or auxiliary pump to the vacuum-type booster",["measuring tire air","checking oil","testing fuel"],"Vacuum supply.")
H("877.d.4.K",4,"Low engine vacuum at the booster is most likely to cause:","a hard brake pedal and reduced assist",["a soft tire","better mileage","a louder radio"],"Less assist.")
H("877.d.4.L",3,"A student explains that a hybrid's electric motor acts as a generator when the driver slows down, sending energy to the battery. She is describing:","the operation of a regenerative braking system",["a hand brake","a tire rotation","an exhaust system"],"Regeneration.")
H("877.d.4.L",4,"Regenerative braking improves efficiency because it:","recovers some motion energy that would be lost as heat",["adds more friction","uses more fuel","wastes energy"],"Energy recovery.")
H("877.d.5.A",3,"A student compares how current flows when three bulbs are connected in a single loop and when they are connected side by side. She is demonstrating:","knowledge of series, parallel and series-parallel circuits",["fuel flow","brake lines","tire patterns"],"Circuit types.")
H("877.d.5.A",4,"In a series circuit, if one bulb burns out, the other bulbs:","go out, because the path is broken",["stay on","get brighter","turn on twice"],"One path.")
H("877.d.5.B",3,"A technician sets her meter to DC volts and reads 12.6 volts across the battery terminals. She is demonstrating:","proper use of a digital multimeter to measure voltage",["fuel testing","tire testing","brake testing"],"DMM use.")
H("877.d.5.B",4,"To measure resistance with a digital multimeter, the circuit should be:","de-energized and the component isolated",["fully powered","overloaded","live with the engine running"],"Never measure ohms on a live circuit.")
H("877.d.5.C",3,"A technician follows lines on a wiring diagram from the fuse, through a switch and relay, to the horn. She is:","using wiring diagrams to trace electrical circuits",["guessing","painting","measuring oil"],"Trace the circuit.")
H("877.d.5.C",4,"On a wiring diagram, a zig-zag line usually represents a:","resistor",["battery","fuse","switch"],"Standard symbols.")
H("877.d.5.D",3,"A technician learns that a wire rubbing on the body can cause a fuse to blow repeatedly. She is demonstrating knowledge of:","the causes and effects of shorts, grounds, opens and resistance problems",["tire wear","fluid levels","paint finishes"],"Circuit faults.")
H("877.d.5.D",4,"An 'open' in a wiring circuit means:","there is a break in the path and current cannot flow",["current flows too much","the circuit is perfect","the battery is full"],"Open equals break.")
H("877.d.5.E",3,"A technician checks that a replacement battery matches the vehicle's required cold cranking amps and group size. She is:","confirming proper battery capacity for the vehicle application",["guessing","ignoring ratings","painting"],"Match the battery.")
H("877.d.5.E",4,"Cold cranking amps (CCA) rating measures a battery's ability to:","start an engine in cold temperatures",["light the radio","charge the tires","fill the tank"],"CCA means cold start power.")
H("877.d.5.F",3,"A technician measures 12.2 volts at rest across a battery and compares it with a chart to estimate its charge. She is performing:","a battery state-of-charge test",["a tire test","a brake test","an alignment"],"Voltage indicates charge.")
H("877.d.5.F",4,"A fully charged 12-volt battery at rest should read about:","12.6 volts",["9 volts","14.5 volts","6 volts"],"Full charge is 12.6.")
H("877.d.5.G",3,"A technician scrubs corrosion from the terminals, tops off the cells with distilled water where possible and checks the case for cracks. She is:","inspecting and cleaning the battery and checking its condition",["ignoring corrosion","painting","guessing"],"Battery care.")
H("877.d.5.G",4,"Baking soda and water are commonly used to clean battery terminals because they:","neutralize acid corrosion",["add acid","paint the terminals","raise the voltage"],"Neutralizes acid.")
H("877.d.5.H",3,"A technician clamps an amp probe on the starter cable and reads the current while the engine cranks. She is performing:","a starter current draw test",["a fuel test","a tire test","an oil test"],"Starter draw.")
H("877.d.5.H",4,"A starter that draws much more current than the specification usually has:","a worn or binding starter, or a mechanical problem",["a perfect motor","a new battery only","low washer fluid"],"High draw means trouble.")
H("877.d.5.I",3,"A technician uses a test light and a meter to check a blown fuse, a tripped circuit breaker and a clicking relay. She is:","inspecting and testing fusible links, circuit breakers, fuses and relays",["washing wipers","painting wires","guessing"],"Protection devices.")
H("877.d.5.I",4,"A fuse should always be replaced with one that has:","the same amp rating as the original",["a higher amp rating","a much lower rating","no rating"],"Match the rating.")
H("877.d.5.J",3,"With the engine running at 2,000 rpm, a technician measures 14.2 volts at the battery and compares it with the specification. She is performing:","a charging system output test",["a tire test","a brake test","a fuel test"],"Charging output.")
H("877.d.5.J",4,"A charging system voltage under 12 volts with the engine running suggests:","the alternator is not charging",["a perfect charge","an overcharge","a bad tire"],"Alternator trouble.")
H("877.d.5.K",3,"A technician inspects the alternator belt for cracks, checks its tension and examines the pulley. She is:","inspecting, adjusting or replacing the alternator drive belt",["ignoring belts","guessing","painting"],"Belt and pulley.")
H("877.d.5.K",4,"A loose alternator belt can cause:","low charging output and a squeal",["extra charging","better mileage","a cooler engine"],"Slipping belt.")
H("877.d.5.L",3,"A technician turns the key on and verifies that the fuel, temperature and battery gauges and warning lights respond. She is:","verifying the operation of instrument panel gauges and warning lights",["guessing","skipping checks","painting"],"Dash check.")
H("877.d.5.L",4,"A temperature gauge stuck at cold with a hot engine may indicate:","a faulty sender or gauge circuit",["a perfect system","low tire pressure","an oil change due"],"Faulty sensor.")
H("877.d.5.M",3,"A technician walks around the car checking headlights, brake lights, turn signals and sockets for corrosion. She is:","inspecting interior and exterior lamps and sockets",["ignoring lights","guessing","painting"],"Lamp check.")
H("877.d.5.M",4,"If a single turn-signal blinks much faster than normal, the likely cause is:","a burned-out bulb on that side",["a full tank","a new battery","a clean windshield"],"Fast flash means bulb out.")
H("877.d.5.N",3,"A technician tests the wiper speeds and the washer spray and installs new blades on a car with streaking. She is:","verifying windshield wiper and washer operation and replacing blades",["ignoring wipers","painting","guessing"],"Wipers.")
H("877.d.5.N",4,"Wiper blades that leave streaks and chatter across the glass most likely need:","replacement because the rubber is worn",["more washer fluid only","a new tire","an alignment"],"Worn blades streak.")
H("877.d.6.A",3,"A technician checks the underhood label to identify whether the A/C uses R-134a or R-1234yf and puts on gloves and goggles. She is:","identifying the refrigerant type and the safety and environmental concerns",["guessing","ignoring labels","avoiding safety"],"Know your refrigerant.")
H("877.d.6.A",4,"Venting refrigerant into the air is a problem because it:","harms the environment and is regulated by law",["is harmless","saves money legally","is required"],"Recover refrigerant.")
H("877.d.6.B",3,"A technician squeezes the upper and lower radiator and heater hoses on a cold engine, looking for cracks, swelling or soft spots. She is:","inspecting the engine cooling and heater system hoses",["ignoring hoses","painting","guessing"],"Hose check.")
H("877.d.6.B",4,"A coolant hose that feels mushy near the clamp should be:","replaced before it bursts",["ignored","painted","taped"],"Soft hoses fail.")
H("877.d.6.C",3,"A technician switches the climate control through every mode, checking that air comes from each outlet and replaces a dirty cabin filter. She is:","inspecting the A/C-heater ducts, doors, hoses, cabin filters and outlets",["ignoring vents","guessing","painting"],"Climate check.")
H("877.d.6.C",4,"A clogged cabin air filter commonly causes:","weak airflow from the vents and musty odors",["a stronger blower","brighter lights","better braking"],"Dirty filter restricts air.")
H("877.d.6.D",3,"A technician looks through the grille and finds bugs and leaves packed across the front of the A/C condenser. She is:","inspecting the condenser for airflow restrictions",["ignoring debris","guessing","painting"],"Clear airflow.")
H("877.d.6.D",4,"A condenser blocked by debris reduces A/C performance because it:","cannot shed heat from the refrigerant",["cools too much","stores fuel","filters air"],"Heat rejection.")
H("877.d.6.E",3,"A technician notes that the A/C compressor in a hybrid is driven by a high-voltage motor and follows the service precautions. She is:","identifying hybrid vehicle A/C electrical circuits and the service precautions",["guessing","ignoring risks","painting"],"High-voltage awareness.")
H("877.d.6.E",4,"Before servicing high-voltage components on a hybrid, a technician should:","follow the manufacturer's procedure and wear insulated gloves",["touch orange cables bare-handed","guess the voltage","skip the manual"],"Orange cables are high voltage.")
H("877.d.7.A",3,"A technician compares ATF used in an automatic transmission and gear oil used in a manual gearbox. She is:","identifying the different fluid types used in automatic and manual transmissions",["comparing paints","comparing tires","comparing wipers"],"Right fluid.")
H("877.d.7.A",4,"Using the wrong fluid in an automatic transmission can:","cause slipping and damage",["improve shifting","save fuel","extend life"],"Specified fluid only.")
H("877.d.7.B",3,"A technician checks the service manual to find a transaxle's fluid type and refill capacity before a service. She is:","identifying the fluid type and capacity required using service information",["guessing","ignoring data","using any fluid"],"Look it up.")
H("877.d.7.B",4,"Overfilling a transmission with fluid can cause:","foaming and leaks",["better cooling","longer life","quieter shifting"],"Overfill is harmful.")
H("877.d.7.C",3,"A technician warms the engine, shifts through the gears, and checks the dipstick for the proper level. She is:","checking the fluid level in a transmission equipped with a dipstick",["checking oil","checking coolant","checking washer fluid"],"Dipstick check.")
H("877.d.7.C",4,"Most automatic transmission dipsticks should be read with the engine:","running and the transmission at operating temperature",["off and cold","off and hot","off and in neutral only"],"Check hot and running.")
H("877.d.7.D",3,"A technician removes a fill plug on the side of a transaxle with no dipstick to check the level. She is:","checking the fluid level in a transmission not equipped with a dipstick",["checking oil","checking coolant","checking washer fluid"],"Fill plug check.")
H("877.d.7.D",4,"On a transmission with a side fill plug, the level is correct when fluid:","just reaches the bottom of the fill hole",["pours out wildly","is 2 inches below","fills past the top"],"Level with the hole.")
H("877.d.7.E",3,"A technician sees fluid that is dark, smells burnt and drips from a seal. She is:","checking the fluid condition and inspecting for leaks",["ignoring fluid","guessing","painting"],"Condition and leaks.")
H("877.d.7.E",4,"Burnt-smelling transmission fluid usually indicates:","overheating and clutch wear",["a new fluid","a clean unit","a cold engine"],"Burnt means damage.")
H("877.d.7.F",3,"A technician drops the pan, replaces the filter and gasket and refills an automatic transmission to the specified amount. She is:","draining and replacing the fluid and filter in an automatic transmission",["changing oil","changing coolant","changing tires"],"ATF service.")
H("877.d.7.F",4,"The old fluid and filter from a transmission service should be:","disposed of according to environmental regulations",["dumped","burned","poured down a drain"],"Regulated waste.")
H("877.d.7.G",3,"A technician removes a gearbox's drain plug, lets the oil drain and refills through the fill plug with the specified gear oil. She is:","draining and replacing the fluid in a manual transmission or transaxle",["changing coolant","changing tires","changing wipers"],"Manual service.")
H("877.d.7.G",4,"Metal particles found on the magnetic drain plug of a manual transmission may indicate:","internal gear or bearing wear",["a perfect gearbox","a new fluid","a clean filter"],"Wear debris.")
H("877.d.7.H",3,"A technician pries on the engine and transmission mounts with a bar and looks for cracked rubber or movement. She is:","inspecting power train mounts",["checking tires","checking oil","checking wipers"],"Mount check.")
H("877.d.7.H",4,"A worn engine mount can cause:","vibration and clunking when accelerating",["better mileage","a cooler engine","quieter shifting"],"Excess movement.")
H("877.d.8.A",3,"A technician locates the mass airflow sensor, the throttle position sensor and the oxygen sensor on an engine and explains what each does. She is:","inspecting and explaining electrical and electronic components, sensors and actuators",["painting","guessing","avoiding electronics"],"Sensors and actuators.")
H("877.d.8.A",4,"An oxygen sensor measures:","the oxygen content of the exhaust gases",["tire pressure","oil level","coolant temperature only"],"O2 sensor.")
H("877.d.8.B",3,"A technician connects a vacuum gauge to the intake manifold and reads the engine's idle vacuum. She is performing:","an engine absolute manifold pressure test",["a tire test","a brake test","an oil test"],"Vacuum test.")
H("877.d.8.B",4,"A steady, low vacuum reading at idle can indicate:","a vacuum leak or a mechanical problem",["perfect health","a full tank","a new battery"],"Low vacuum is a clue.")
H("877.d.8.C",3,"A technician warms the engine and compares the scan tool's coolant temperature with the thermostat's rating. She is:","verifying the engine operating temperature",["measuring tires","measuring oil","measuring fuel"],"Check temperature.")
H("877.d.8.C",4,"An engine that never reaches normal operating temperature probably has:","a thermostat stuck open",["a clogged filter","a bad tire","a dead radio"],"Stuck-open thermostat.")
H("877.d.8.D",3,"A technician removes the spark plugs, checks the gap and inspects the wires and coils for cracks. She is:","removing and replacing spark plugs and inspecting secondary ignition components",["painting","guessing","avoiding service"],"Plug service.")
H("877.d.8.D",4,"Over-tightening a spark plug in an aluminum head can:","strip the threads",["improve the seal","reduce wear","cool the engine"],"Use proper torque.")
H("877.d.8.E",3,"A technician learns that a vehicle's emissions monitors must run to completion before it can pass a readiness test. She is describing:","the importance of operating all OBD II monitors for repair verification",["tire monitoring","oil monitoring","radio monitoring"],"Complete monitors.")
H("877.d.8.E",4,"After clearing codes, the technician should drive the vehicle through a drive cycle so that:","the OBD II monitors can run and confirm the repair",["the codes stay hidden","the battery drains","the tires wear"],"Verify with monitors.")
H("877.d.8.F",3,"A technician connects a scan tool and records the diagnostic trouble codes, the monitor status and freeze-frame data. She is:","retrieving and recording diagnostic trouble codes and OBD II monitor status",["ignoring data","guessing","painting"],"Record data.")
H("877.d.8.F",4,"A code P0300 on a scan tool indicates:","a random or multiple cylinder misfire",["a weak tire","low wiper fluid","a full tank"],"P0300 = random misfire.")
H("877.d.8.G",3,"A technician tilts the airbox, examines the air filter for dirt, replaces it and checks the intake duct for cracks. She is:","inspecting, servicing or replacing air filters, filter housings and intake ducts",["ignoring filters","guessing","painting"],"Air filter service.")
H("877.d.8.G",4,"A restricted air filter can cause:","reduced power and poor fuel economy",["better mileage","more power","a cooler engine"],"Starved engine.")
H("877.d.8.H",3,"A technician relieves fuel pressure, disconnects the lines and installs a new in-line fuel filter in the right direction. She is:","replacing fuel filters",["changing tires","changing wipers","changing mirrors"],"Filter replacement.")
H("877.d.8.H",4,"Before disconnecting a fuel line, a technician should first:","relieve the fuel system pressure",["start the engine","smoke nearby","remove the battery cap"],"Safety first.")
H("877.d.8.I",3,"A technician inspects the exhaust manifold, pipes, muffler and catalytic converter for leaks and corrosion. She is:","inspecting the integrity of the exhaust system",["ignoring exhaust","guessing","painting"],"Exhaust check.")
H("877.d.8.I",4,"An exhaust leak ahead of the oxygen sensor can:","cause false readings and poor fuel control",["help the engine","cool the exhaust","clean the sensor"],"Leaks fool the sensor.")
H("877.d.8.J",3,"A technician checks the PCV valve and hoses for clogs and verifies the system draws crankcase vapors. She is:","inspecting, testing and servicing the positive crankcase ventilation system",["ignoring PCV","painting","guessing"],"PCV service.")
H("877.d.8.J",4,"A clogged PCV valve may cause:","oil leaks and sludge from excessive crankcase pressure",["better efficiency","less wear","cooler running"],"Pressure builds.")
H("877.d.9.A",3,"A technician reads a tire sidewall and finds the size, load rating, speed rating and the DOT manufacturing code. She is:","identifying and interpreting tire sidewall data information",["ignoring the tire","guessing","painting"],"Read the sidewall.")
H("877.d.9.A",4,"In a tire size of P215/60R16, the '16' refers to the:","wheel diameter in inches",["tire width in millimeters","aspect ratio","speed rating"],"Rim diameter.")
H("877.d.9.B",3,"A technician inserts a tread depth gauge in the groove and reads 3/32 inch. She is demonstrating:","tire tread depth measuring procedures using industry standards",["guessing","ignoring wear","painting"],"Measure tread.")
H("877.d.9.B",4,"A tire is generally considered worn out when the tread depth is:","2/32 inch or less",["8/32 inch","10/32 inch","12/32 inch"],"Wear bars at 2/32.")
H("877.d.9.C",3,"A technician spins a wheel on a balancer, adds weights to the rim and rechecks that it runs smooth. She is demonstrating:","tire and wheel balance such as static and dynamic balance",["tire inflation","tire rotation","brake adjustment"],"Balance.")
H("877.d.9.C",4,"An unbalanced front tire commonly causes:","a vibration in the steering wheel at highway speed",["lower tire pressure","a dead battery","a noisy radio"],"Vibration.")
H("877.d.9.D",3,"A technician uses a dial indicator to measure how much a wheel wobbles side to side and up and down. She is:","demonstrating tire and wheel measurements such as radial and lateral runout",["measuring fuel","measuring oil","measuring coolant"],"Runout.")
H("877.d.9.D",4,"Excessive wheel runout can cause:","vibration and uneven tire wear",["better handling","longer tire life","quieter ride"],"Wobble causes vibration.")
H("877.d.9.E",3,"A technician shakes the inner and outer tie rod ends and checks for play and torn boots. She is:","inspecting steering linkage components and mounts",["ignoring steering","guessing","painting"],"Steering check.")
H("877.d.9.E",4,"Worn tie rod ends often cause:","loose steering and uneven tire wear",["better steering","brighter lights","a cooler engine"],"Play in steering.")
H("877.d.9.F",3,"A technician cleans the old grease from a bearing, inspects the rollers, repacks it and installs it with a new seal. She is:","removing, cleaning, inspecting and repacking wheel bearings",["painting","guessing","avoiding service"],"Bearing service.")
H("877.d.9.F",4,"A wheel bearing that is worn out will often:","make a humming or growling noise that changes with speed",["silence the car","improve steering","reduce wear"],"Noisy bearing.")
H("877.d.9.G",3,"A technician pushes down on each corner of the car and watches how many times it bounces, then looks for oil on the strut body. She is:","inspecting shock absorbers and struts for leakage and performance",["ignoring shocks","guessing","painting"],"Bounce test.")
H("877.d.9.G",4,"A shock or strut that is leaking fluid usually needs:","replacement",["more air","more tape","no action"],"Leaks mean failure.")
H("877.d.9.H",3,"A technician presses out a damaged wheel stud and installs a new one, then tightens the lug nuts in a star pattern. She is:","demonstrating wheel stud replacement and installation of wheel and tire assemblies",["painting","guessing","avoiding repair"],"Stud replacement.")
H("877.d.9.H",4,"Lug nuts should be tightened in a star pattern to:","seat the wheel evenly and avoid warping the rotor",["save time","save nuts","look neat"],"Even torque.")
H("877.d.9.I",3,"A technician uses a TPMS tool to read each wheel sensor's pressure and ID before a tire change. She is:","identifying and testing the Tire Pressure Monitoring System",["measuring tread","measuring brake wear","measuring oil"],"TPMS.")
H("877.d.9.I",4,"A TPMS warning light turning on usually means one or more tires:","are significantly under-inflated",["are overfilled","are new","are balanced"],"Low tire pressure.")
H("877.d.9.J",3,"A technician uses a tire machine to break the bead, remove the tire from the rim and mount a new one. She is:","dismounting and mounting a tire on a wheel and reinstalling the assembly",["painting wheels","guessing","avoiding tire work"],"Tire changing.")
H("877.d.9.J",4,"After mounting a tire, the technician should always:","inflate to the specified pressure and balance the wheel",["leave it flat","over-inflate","skip balancing"],"Pressure and balance.")
H("877.d.9.K",3,"A technician moves the front tires to the rear and the rears to the front, following the pattern in the owner's manual. She is:","rotating tires according to the manufacturer's recommendations",["ignoring tires","guessing","painting"],"Rotate tires.")
H("877.d.9.K",4,"Regular tire rotation helps a vehicle by:","wearing the tires evenly so they last longer",["raising the speed","using more fuel","reducing grip"],"Even wear.")

